from pathlib import Path
import json,re,hashlib
D=Path('docs/audit/evidence/g0-legacy-confirmation-20261020');old=Path('docs/audit/evidence/g0-legacy-local-20261020');sha=lambda b:'sha256:'+hashlib.sha256(b).hexdigest()
