doc=old/'confirmation-draft.md';req=json.loads(re.search(r'```json\s*([\s\S]*?)```',doc.read_text())[1])['request'];assert req['inputsDigest']==pre['g0ScopeDigest'];assert sha(doc.read_bytes())==pre['approvedDraftSha256']
record={'schema':'quantos-user-acceptance-confirmation/v1','mode':'AGENT_DRAFT_USER_CONFIRMATION','decision':'CONFIRMED','approver':'ProjectUser','identity':'ProjectUser (current conversation)','confirmedAt':'2026-10-20T13:47:14Z','request':req,'document':str(doc),'documentSha256':pre['approvedDraftSha256'],'documentCommit':pre['packetCommit'],'confirmationSource':{'kind':'USER_MESSAGE','text':'人工已确认 G0 legacy 迁移后完整确认稿。继续执行 G0/PROVIDER:ALL 确认收口与 READY 评估，依据开发计划和最新 AGENTS.md，核验同一工程输入、保存验收证据并同步计划，生成本地 Git 提交；不做无关全闭包复验，不使用生产凭据、不推送或部署。'},'approvedTechnicalManifest':{'path':str(old/'function-attempt-02/function-receipt.json'),'sha256':pre['engineeringReceiptSha256'],'commit':pre['packetCommit']},'approvedSourceCommit':pre['sourceCommit'],'scopeAdmission':'FUNCTION_ONLY','scopeSummary':'Migrated G0 functional scope at frozen4fdc67b4; evaluate G0 and PROVIDER:ALL DEVELOPMENT READY only after same1652-input, original ALL approval and legacy removal proof checks. Original engineering and failure/skip history remain bound to original source.','formalAccepted':False,'releaseAccepted':False,'runtimeAdmission':'DENIED'}
assert not (D/'user-confirmation.json').exists();save(D/'user-confirmation.json',record);approval={'record':str(D/'user-confirmation.json'),'recordSha256':sha((D/'user-confirmation.json').read_bytes())};save(D/'approval.json',approval)
save('docs/gate-records/G0-current-scope-confirmations.json',{'schema':'quantos-g0-scope-confirmations/v2','status':'CONFIRMED','scopeDigest':req['inputsDigest'],'approval':approval,'reason':'ProjectUser explicitly confirmed the immutable migrated G0 complete draft; original source/engineering receipt preserved. This record grants only the human condition for same-input functional G0/ALL admission, never a later source, runtime, integration or release.'})
print('Actual USER_MESSAGE recorded; immutable draft/source/receipt and scopeDigest bound; no engineering status inferred')
